  /// adults + children only, matching how the availability service counts and
  /// how every other booking site does.
  void _search() {
    final String town = _whereCtrl.text.trim();

    Navigator.of(context).pushNamed(
      StayRoutes.results,
      arguments: <String, dynamic>{
        'criteria': StaySearchCriteria(
          town: town.isEmpty ? null : town,
          checkIn: _dates?.start,
          checkOut: _dates?.end,
          guests: _countedGuests,
        ),
      },
    );
  }

